"""Generated by portomatic v0.13 apply prompt, hand-completed by Patch Author.

Spec: daqifi-core/src/Daqifi.Core/Firmware/FirmwareVersion.cs (commit e8d84af).

Mirrors the C# behavior including:
- Default minor/patch when omitted ("3" → 3.0.0)
- Optional `v` / `V` prefix
- Pre-release labels (alpha/beta/rc) with precedence ordering
- Release > rc > beta > alpha
- Unparseable strings sort before valid versions in compare()
"""
import pytest

from daqifi.firmware import FirmwareVersion
from daqifi.firmware.version import compare


# ---------------------------------------------------------------------------
# parse() — happy path + edge cases
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("inp,expected", [
    ("3.2.0",       (3, 2, 0, None, 0)),
    ("v3.2.0",      (3, 2, 0, None, 0)),
    ("V3.2.0",      (3, 2, 0, None, 0)),
    ("3.2",         (3, 2, 0, None, 0)),
    ("3",           (3, 0, 0, None, 0)),
    ("v 3.2.0",     (3, 2, 0, None, 0)),  # whitespace after v allowed
    ("  v3.2.0  ",  (3, 2, 0, None, 0)),  # outer whitespace stripped
    ("3.2.0b2",     (3, 2, 0, "b", 2)),
    ("v1.0.0rc1",   (1, 0, 0, "rc", 1)),
    ("1.0.0alpha",  (1, 0, 0, "alpha", 0)),
    # Pre-release labels canonicalize to lowercase so equality / hash
    # agree with ordering (Qodo PR #52 review #1).
    ("1.0.0BETA",   (1, 0, 0, "beta", 0)),
    ("2.0.0pre",    (2, 0, 0, "pre", 0)),
])
def test_parse_round_trips_to_expected_fields(inp, expected):
    v = FirmwareVersion.parse(inp)
    assert v is not None, f"failed to parse: {inp!r}"
    assert (v.major, v.minor, v.patch, v.pre_label, v.pre_number) == expected


@pytest.mark.parametrize("inp", [
    None,
    "",
    "   ",
    "not-a-version",
    "v",
    "1.2.3.4.5",  # extra dots beyond major.minor.patch
    "abc",
    "1..2",       # malformed
])
def test_parse_returns_none_for_invalid(inp):
    assert FirmwareVersion.parse(inp) is None


# ---------------------------------------------------------------------------
# is_pre_release
# ---------------------------------------------------------------------------

def test_release_version_is_not_pre_release():
    v = FirmwareVersion.parse("3.2.0")
    assert v is not None
    assert v.is_pre_release is False


@pytest.mark.parametrize("inp", ["3.2.0a1", "3.2.0b2", "3.2.0rc1", "3.2.0alpha", "3.2.0beta", "3.2.0pre"])
def test_pre_release_versions_flag_correctly(inp):
    v = FirmwareVersion.parse(inp)
    assert v is not None
    assert v.is_pre_release is True


# ---------------------------------------------------------------------------
# __str__ — round-trip
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("inp,expected_str", [
    ("3.2.0",      "3.2.0"),
    ("v3.2.0",     "3.2.0"),    # canonical: no leading v
    ("3",          "3.0.0"),     # canonical: zero-fill
    ("3.2.0b2",    "3.2.0b2"),
    ("3.2.0rc1",   "3.2.0rc1"),
    ("3.2.0alpha", "3.2.0alpha"),  # bare label, no number → no trailing number
])
def test_str_canonicalizes(inp, expected_str):
    v = FirmwareVersion.parse(inp)
    assert v is not None
    assert str(v) == expected_str


# ---------------------------------------------------------------------------
# Comparison operators (<, >, <=, >=, ==)
# ---------------------------------------------------------------------------

def test_release_is_greater_than_pre_release_at_same_core_version():
    release = FirmwareVersion.parse("3.2.0")
    rc = FirmwareVersion.parse("3.2.0rc1")
    beta = FirmwareVersion.parse("3.2.0b2")
    alpha = FirmwareVersion.parse("3.2.0a1")
    assert release > rc > beta > alpha


def test_higher_major_beats_lower_major_regardless_of_pre_release():
    v3_release = FirmwareVersion.parse("3.0.0")
    v2_release = FirmwareVersion.parse("2.99.99")
    assert v3_release > v2_release


def test_minor_and_patch_break_major_ties():
    v320 = FirmwareVersion.parse("3.2.0")
    v321 = FirmwareVersion.parse("3.2.1")
    v330 = FirmwareVersion.parse("3.3.0")
    assert v321 > v320
    assert v330 > v321


def test_pre_release_number_breaks_label_ties():
    b1 = FirmwareVersion.parse("3.2.0b1")
    b2 = FirmwareVersion.parse("3.2.0b2")
    assert b2 > b1


def test_equal_versions_compare_equal():
    a = FirmwareVersion.parse("3.2.0rc1")
    b = FirmwareVersion.parse("v3.2.0rc1")
    assert a == b
    assert (a > b) is False
    assert (a < b) is False


def test_records_are_value_equal_via_dataclass_frozen():
    a = FirmwareVersion(3, 2, 0, None, 0)
    b = FirmwareVersion(3, 2, 0, None, 0)
    assert a == b
    assert hash(a) == hash(b)


# ---------------------------------------------------------------------------
# compare() — module-level helper
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("left,right,expected_sign", [
    ("3.2.0",   "3.2.0",   0),
    ("3.2.0",   "3.2.1",  -1),
    ("3.2.1",   "3.2.0",   1),
    ("3.2.0rc1", "3.2.0",  -1),
    ("3.2.0",    "3.2.0rc1", 1),
    (None,      None,      0),
    (None,      "3.2.0",  -1),  # None sorts before valid
    ("3.2.0",   None,      1),
    ("garbage", "3.2.0",  -1),  # unparseable sorts before valid
    ("3.2.0",   "garbage", 1),
])
def test_compare_returns_expected_sign(left, right, expected_sign):
    result = compare(left, right)
    if expected_sign == 0:
        assert result == 0
    elif expected_sign < 0:
        assert result < 0
    else:
        assert result > 0


# ---------------------------------------------------------------------------
# Dot-separated SemVer pre-release form (#10)
# ---------------------------------------------------------------------------

@pytest.mark.parametrize("inp,expected", [
    # Standard SemVer / GitHub release tag form
    ("3.0.0-beta.1",   (3, 0, 0, "beta", 1)),
    ("v3.0.0-beta.1",  (3, 0, 0, "beta", 1)),
    ("1.2.3-rc.5",     (1, 2, 3, "rc", 5)),
    ("1.2.3-alpha.10", (1, 2, 3, "alpha", 10)),
    # Dash + label without trailing number
    ("3.0.0-beta",     (3, 0, 0, "beta", 0)),
    ("3.0.0-rc",       (3, 0, 0, "rc", 0)),
    ("v1.0.0-alpha",   (1, 0, 0, "alpha", 0)),
])
def test_parse_accepts_dot_separated_semver_pre_release(inp, expected):
    """Closes #10: GitHub release tags + SemVer use ``3.0.0-beta.1`` shape;
    the original C# regex only accepted ``3.0.0beta1``. Both shapes parse
    to the same FirmwareVersion fields after this widening."""
    v = FirmwareVersion.parse(inp)
    assert v is not None, f"failed to parse: {inp!r}"
    assert (v.major, v.minor, v.patch, v.pre_label, v.pre_number) == expected


def test_dot_form_and_concat_form_compare_equal():
    """3.0.0-beta.1 and 3.0.0beta1 are the same version — comparison
    must agree across both shapes so callers don't get version drift
    based on which form upstream emits."""
    dot = FirmwareVersion.parse("3.0.0-beta.1")
    concat = FirmwareVersion.parse("3.0.0beta1")
    assert dot == concat
    assert hash(dot) == hash(concat)


def test_label_case_normalized_so_equality_agrees_with_compare():
    """Qodo PR #52 review #1: parse() now lowercases the label so two
    inputs that differ only in case (firmware self-report 'BETA' vs
    GitHub release tag 'beta') are == and hash-equal. Without this,
    compare() would return 0 (same precedence rank, same number) but
    dataclass __eq__ would return False (different label strings)."""
    upper = FirmwareVersion.parse("3.0.0BETA")
    lower = FirmwareVersion.parse("3.0.0beta")
    dash_upper = FirmwareVersion.parse("3.0.0-BETA")
    dash_lower = FirmwareVersion.parse("3.0.0-beta")
    assert upper == lower == dash_upper == dash_lower
    assert hash(upper) == hash(lower) == hash(dash_upper) == hash(dash_lower)


def test_dot_form_pre_release_sorts_below_release():
    rel = FirmwareVersion.parse("3.0.0")
    pre = FirmwareVersion.parse("3.0.0-beta.1")
    assert pre is not None and rel is not None
    assert pre < rel


# ---------------------------------------------------------------------------
# Cross-type comparison protocol
# ---------------------------------------------------------------------------

def test_lt_against_non_firmware_version_returns_not_implemented():
    v = FirmwareVersion.parse("3.2.0")
    with pytest.raises(TypeError):
        # `<` between FirmwareVersion and str should raise TypeError
        # because __lt__ returns NotImplemented and str's reverse op
        # also doesn't know FirmwareVersion.
        _ = v < "3.2.0"
